// Camera angle calibration table (periodic, 36 entries, -180..+170 deg in 10 deg steps).
// Generated by tools/camera_angle_calib.py (fit on logs of the pendulum swung past upright, encoder = truth).
// camCalibrate(z0): z0 = -camera angle (sign already applied), wrapped to (-pi, pi]; returns the corrected angle
// z0 + c(z0) in the encoder's convention (0 = upright). c is linearly interpolated between the entries and
// absorbs the zero offset. The table below is the IDENTITY version: a constant -0.96 deg, the value measured
// over large swings, so the firmware behaves as before until a fitted table replaces it.
#pragma once
#include <math.h>

constexpr int CAM_CAL_N = 36;
constexpr float CAM_CAL_STEP_RAD = 2.0f * 3.14159265358979f / CAM_CAL_N;
constexpr float CAM_CAL_RAD[CAM_CAL_N] = {-0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f, -0.016755f};

static inline float camCalWrap(float a) {
    while (a > 3.14159265358979f) a -= 2.0f * 3.14159265358979f;
    while (a <= -3.14159265358979f) a += 2.0f * 3.14159265358979f;
    return a;
}

static inline float camCalibrate(float z0) {
    const float x = (z0 + 3.14159265358979f) / CAM_CAL_STEP_RAD;
    int i = (int)x;
    if (i < 0) i = 0;
    const float f = x - (float)i;
    const float a = CAM_CAL_RAD[i % CAM_CAL_N];
    const float b = CAM_CAL_RAD[(i + 1) % CAM_CAL_N];
    return camCalWrap(z0 + a + (b - a) * f);
}
